head.script:
/**
 * WebSquare5 Work Schedule Dashboard Page Controller
 */
var scwin = {};

// Initial Target Master Data
scwin.TARGET_ITEMS = [
    { id: 'EQ-HVAC-101', name: '중앙 냉난방 공조기 1호기 (Main HVAC System)', category: '설비' },
    { id: 'EQ-ELEV-204', name: '화물/승객용 엘리베이터 B동 (Freight Elevator)', category: '설비' },
    { id: 'EQ-CONV-302', name: '물류 이송 컨베이어 라인 #2 (Conveyor Line)', category: '설비' },
    { id: 'EQ-GEN-105', name: '비상 자가발전기 세트 (300kW Backup Power)', category: '설비' },
    { id: 'EQ-PUMP-401', name: '메인 급수 부스터 펌프 (Water Booster Pump)', category: '설비' },
    { id: 'EQ-SOLAR-503', name: '옥상 태양광 발전 인버터 (Solar Inverter)', category: '설비' },
    { id: 'EQ-COMP-601', name: '산업용 에어 컴프레셔 (Air Compressor #1)', category: '설비' },
    { id: 'MAT-BOX-301', name: '표준 물류 포장 박스 세트 (Lot #B42)', category: '자재입출고' },
    { id: 'MAT-PAL-002', name: '플라스틱 표준 파렛트 (1100x1100mm)', category: '자재입출고' },
    { id: 'MAT-TAP-005', name: '포장용 테이프 및 완충재 묶음', category: '자재입출고' },
    { id: 'MAT-LUB-001', name: '산업용 기계 윤활유 드럼 (200L)', category: '자재입출고' },
    { id: 'MAT-LED-102', name: '고효율 LED 조명 교체용 모듈', category: '자재입출고' },
    { id: 'MAT-FLT-008', name: '공조기 헤파/프리 필터 Replacement Kit', category: '자재입출고' },
    { id: 'FAC-PARK-001', name: '지하 주차장 무인 차단기 정산 시스템', category: '시설/인프라' },
    { id: 'FAC-FIRE-002', name: '메인 소방 수신기 및 스프링클러 배관', category: '시설/인프라' },
    { id: 'FAC-NET-003', name: 'MDF 통신실 메인 네트워크 스위치 랙', category: '시설/인프라' }
];

// Initial Sample Schedule Data
scwin.INITIAL_SCHEDULES = [
    { id: 'row-1', chk: '0', site: '서울본사', fab: 'A동 3층', type: 'PM', subcat: '정기 점검', utIds: 'EQ-HVAC-101', content: '분기 정기 공조기 필터 점검 및 냉매 압력 상태 계측' },
    { id: 'row-2', chk: '0', site: '판교센터', fab: '물류존 1', type: '자재입출고', subcat: '원자재 입고', utIds: 'MAT-BOX-301,MAT-PAL-002', content: '신규 물류 표준 포장재 및 파렛트 입고 검수 및 창고 적재' },
    { id: 'row-3', chk: '0', site: '부산센터', fab: 'B동 1층', type: 'CM', subcat: '개선 개조', utIds: 'EQ-CONV-302', content: '컨베이어 이송 벨트 모터 교체 및 속도 제어 인버터 튜닝' },
    { id: 'row-4', chk: '0', site: '서울본사', fab: '지하 2층', type: 'PM', subcat: '정기 점검', utIds: 'EQ-GEN-105', content: '비상 발전기 무부하 시운전 및 배터리 전압 점검' },
    { id: 'row-5', chk: '0', site: '판교센터', fab: '물류존 2', type: '자재입출고', subcat: '부품 출하', utIds: 'MAT-FLT-008', content: '소모성 소모품 및 필터 모듈 출고 불출 처리' }
];

/**
 * Page Onload Lifecycle Hook
 */
scwin.onpageload = function() {
    scwin.initMasterData();
    scwin.initScheduleData();
};

scwin.initMasterData = function() {
    dlt_targetItems.setJSON(scwin.TARGET_ITEMS);
};

scwin.initScheduleData = function() {
    var saved = localStorage.getItem('SK_WORK_SCHEDULE_DATA_WS_V1');
    if (saved) {
        try {
            var parsed = JSON.parse(saved);
            dlt_schedule.setJSON(parsed);
        } catch(e) {
            dlt_schedule.setJSON(scwin.INITIAL_SCHEDULES);
        }
    } else {
        dlt_schedule.setJSON(scwin.INITIAL_SCHEDULES);
    }
    scwin.updateCount();
};

scwin.saveScheduleData = function() {
    var data = dlt_schedule.getAllJSON();
    localStorage.setItem('SK_WORK_SCHEDULE_DATA_WS_V1', JSON.stringify(data));
    scwin.updateCount();
};

scwin.updateCount = function() {
    var total = dlt_schedule.getRowCount();
    if (document.getElementById('txt_total_count')) {
        document.getElementById('txt_total_count').innerText = total;
    }
};

/**
 * Event Handlers
 */
scwin.btnSearch_onclick = function() {
    var keyword = ibx_search.getValue().trim().toLowerCase();
    var site = sbx_site.getValue();
    var type = sbx_type.getValue();

    // Apply filtering to GridView
    for (var i = 0; i < dlt_schedule.getRowCount(); i++) {
        var rowData = dlt_schedule.getRowJSON(i);
        var matchSite = !site || rowData.site === site;
        var matchType = !type || rowData.type === type;
        var matchKeyword = !keyword || 
            (rowData.site && rowData.site.toLowerCase().indexOf(keyword) > -1) ||
            (rowData.fab && rowData.fab.toLowerCase().indexOf(keyword) > -1) ||
            (rowData.subcat && rowData.subcat.toLowerCase().indexOf(keyword) > -1) ||
            (rowData.utIds && rowData.utIds.toLowerCase().indexOf(keyword) > -1) ||
            (rowData.content && rowData.content.toLowerCase().indexOf(keyword) > -1);

        if (matchSite && matchType && matchKeyword) {
            grd_schedule.setRowVisible(i, true);
        } else {
            grd_schedule.setRowVisible(i, false);
        }
    }
};

scwin.btnAddRow_onclick = function() {
    var newRowIdx = dlt_schedule.insertRow();
    var newId = 'row-' + (new Date().getTime());
    dlt_schedule.setCellData(newRowIdx, 'id', newId);
    dlt_schedule.setCellData(newRowIdx, 'chk', '0');
    dlt_schedule.setCellData(newRowIdx, 'site', '서울본사');
    dlt_schedule.setCellData(newRowIdx, 'fab', '신규 구역');
    dlt_schedule.setCellData(newRowIdx, 'type', 'PM');
    dlt_schedule.setCellData(newRowIdx, 'subcat', '정기 점검');
    dlt_schedule.setCellData(newRowIdx, 'utIds', 'EQ-HVAC-101');
    dlt_schedule.setCellData(newRowIdx, 'content', '신규 작업 내용을 입력하세요.');
    scwin.saveScheduleData();
};

scwin.btnQuickAdd_onclick = function() {
    scwin.btnAddRow_onclick();
};

scwin.btnDeleteSelected_onclick = function() {
    var checkedRows = grd_schedule.getCheckedIndex('chk');
    if (checkedRows.length === 0) {
        alert('삭제할 행을 선택하세요.');
        return;
    }
    if (confirm(checkedRows.length + '개 항목을 삭제하시겠습니까?')) {
        dlt_schedule.removeRows(checkedRows);
        scwin.saveScheduleData();
    }
};

scwin.btnReset_onclick = function() {
    if (confirm('모든 데이터를 초기화하시겠습니까?')) {
        localStorage.removeItem('SK_WORK_SCHEDULE_DATA_WS_V1');
        dlt_schedule.setJSON(scwin.INITIAL_SCHEDULES);
        scwin.saveScheduleData();
    }
};

scwin.btnExportCsv_onclick = function() {
    grd_schedule.exportCSV({
        fileName: 'Work_Schedule_WebSquare.csv',
        useHeader: true
    });
};

scwin.grd_schedule_oncellclick = function(row, col) {
    var colId = grd_schedule.getColumnID(col);
    if (colId === 'action') {
        if (confirm('해당 행을 삭제하시겠습니까?')) {
            dlt_schedule.removeRow(row);
            scwin.saveScheduleData();
        }
    }
};
